parameters.query:
insert into leads (customer_id, product_interest, budget, location, purchase_intent, source, status)
values ((select id from customers where phone = $1), $2, $3, $4, $5, 'chat', 'new')
returning id;

insert into tickets (customer_id, type, priority, status)
values ((select id from customers where phone = $1), $2, 'high', 'open')
returning id;

